#include "frozen_lll_prefix.hpp"
#include <set>
#include <functional>
struct Enum{Mat basis;Vec weights,offset,hi;std::set<Vec>points;unsigned steps=0;uint64_t nodes=0;bool complete=true;};
unsigned bits(const I&x){return mpz_sizeinbase(x.get_mpz_t(),2);}
Enum enumerate(const I&p,const I&M,const Quad&t,const Quad&u){Enum e;e.offset={0,0,t[2],u[2]};e.hi={I(3*M),I(9*M*M),I(3*M*M),I(M*M*M)};unsigned B=0;for(int j=0;j<4;j++)B=std::max(B,bits(I(e.hi[j]+1)));for(int j=0;j<4;j++){e.weights[j]=1;e.weights[j]<<=B-bits(I(e.hi[j]+1));}e.basis={Vec{1,0,t[1],u[1]},Vec{0,1,t[0],u[0]},Vec{0,0,p,0},Vec{0,0,0,p}};for(auto&row:e.basis)for(int j=0;j<4;j++)row[j]*=2*e.weights[j];lll(e.basis,e.steps);GS g=gram(e.basis);Vec C;Q radius=0;for(int j=0;j<4;j++){C[j]=e.weights[j]*(e.hi[j]-2*e.offset[j]);I z=e.weights[j]*e.hi[j];radius+=Q(z*z);}std::array<Q,4>target;for(int i=0;i<4;i++){Q dot=0;for(int j=0;j<4;j++)dot+=Q(C[j])*g.s[i][j];target[i]=dot/g.norm[i];}Vec coeff{};
std::function<void(int,Q)> rec=[&](int i,Q used){if(!e.complete)return;if(i<0){Vec x=e.offset;for(int j=0;j<4;j++){I v=0;for(int k=0;k<4;k++)v+=coeff[k]*e.basis[k][j];I den=2*e.weights[j];need(v%den==0,"exact lattice unscale");x[j]+=v/den;if(x[j]<0||x[j]>e.hi[j])return;}need(imod(x[2]-t[0]*x[1]-t[1]*x[0]-t[2],p)==0&&imod(x[3]-u[0]*x[1]-u[1]*x[0]-u[2],p)==0,"primal membership");e.points.insert(x);return;}Q remain=radius-used;if(remain<0)return;Q center=target[i];for(int j=i+1;j<4;j++)center-=Q(coeff[j])*g.mu[j][i];Q bound=remain/g.norm[i];I A=center.get_num(),D=center.get_den();Q square=Q(D*D)*bound;I q=fd(square.get_num(),square.get_den()),T;need(q>=0,"nonnegative square bound");mpz_sqrt(T.get_mpz_t(),q.get_mpz_t());I lo=cd(A-T,D),hi=fd(A+T,D);for(I z=lo;z<=hi;z++){if(e.nodes>=100000){e.complete=false;return;}e.nodes++;coeff[i]=z;Q delta=Q(z)-center;rec(i-1,used+g.norm[i]*delta*delta);if(!e.complete)return;}};rec(3,Q(0));return e;}
using Sol=std::array<I,4>;
std::set<Sol> recover(const Enum&e,const I&M,unsigned&unresolved){std::set<Sol>out;for(auto x:e.points){I S=x[0];if(x[1]!=S*S)continue;if(S>4096){unresolved++;continue;}Poly poly{-x[3],x[2],-S,1};std::vector<I>roots;I top=S<M?S:M;for(I z=0;z<=top&&poly.size()>1;z++){auto val=[&](){I v=0;for(auto it=poly.rbegin();it!=poly.rend();++it)v=v*z+*it;return v;};while(poly.size()>1&&val()==0){Poly q(poly.size()-1);q.back()=poly.back();for(int j=int(q.size())-2;j>=0;j--)q[j]=poly[j+1]+z*q[j+1];need(poly[0]+z*q[0]==0,"integer synthetic division");poly=q;roots.push_back(z);}}if(poly.size()==1){need(roots.size()==3,"cubic root multiplicity");std::sort(roots.begin(),roots.end());do{out.insert({S,roots[0],roots[1],roots[2]});}while(std::next_permutation(roots.begin(),roots.end()));}}return out;}
void vec(std::ostream&o,const Vec&v){o<<'[';for(int j=0;j<4;j++){if(j)o<<',';o<<'"'<<v[j]<<'"';}o<<']';}
void primal_controls(){uint64_t count=0,tuples=0;for(long p:{5L,7L,11L})for(long M:{1L,2L})for(long k=0;k<2;k++){Quad t{I(k),I((k+1)%p),I(k)},u{I((k+1)%p),I(k),I(k)};Enum e=enumerate(I(p),I(M),t,u);need(e.complete,"tiny enumeration complete");std::set<Vec>truth;for(long S=0;S<=3*M;S++)for(long V=0;V<=9*M*M;V++)for(long T=0;T<=3*M*M;T++)for(long U=0;U<=M*M*M;U++){tuples++;auto md=[&](long z){z%=p;return z<0?z+p:z;};if(md(T-t[0].get_si()*V-t[1].get_si()*S-t[2].get_si())==0&&md(U-u[0].get_si()*V-u[1].get_si()*S-u[2].get_si())==0)truth.insert({I(S),I(V),I(T),I(U)});}need(e.points==truth,"independent brute-force four-box set");unsigned unknown=0;auto sols=recover(e,I(M),unknown);need(!unknown,"tiny roots complete");std::set<Sol>oracle;for(long x=0;x<=M;x++)for(long y=0;y<=M;y++)for(long z=0;z<=M;z++){long S=x+y+z,T=x*y+x*z+y*z,U=x*y*z;auto md=[&](long v){v%=p;return v<0?v+p:v;};if(md(T-t[0].get_si()*S*S-t[1].get_si()*S-t[2].get_si())==0&&md(U-u[0].get_si()*S*S-u[1].get_si()*S-u[2].get_si())==0)oracle.insert({I(S),I(x),I(y),I(z)});}need(sols==oracle,"independent ordered-root multiset oracle");count++;}std::cerr<<"tiny_cases="<<count<<" brute_tuples="<<tuples<<'\n';}
int main(int argc,char**argv){auto start=Clock::now();try{need(argc==3,"id input");primal_controls();std::ifstream in(argv[2]);need(bool(in),"public input");std::ostringstream rows;bool comma=false;unsigned cases=0;std::string field;I p,M;while(in>>field>>p>>M){need(std::chrono::duration<double>(Clock::now()-start).count()<65,"native traversal budget");Quad t,u;in>>t[0]>>t[1]>>t[2]>>u[0]>>u[1]>>u[2];need(bool(in),"complete public case");Enum e=enumerate(p,M,t,u);unsigned unresolved=0;auto sol=recover(e,M,unresolved);if(comma)rows<<',';comma=true;rows<<"{\"field\":\""<<field<<"\",\"complete\":"<<(e.complete&&!unresolved?"true":"false")<<",\"enumeration_complete\":"<<(e.complete?"true":"false")<<",\"nodes\":"<<e.nodes<<",\"LLL_steps\":"<<e.steps<<",\"unresolved_root_candidates\":"<<unresolved<<",\"weights\":";vec(rows,e.weights);rows<<",\"offset\":";vec(rows,e.offset);rows<<",\"basis\":[";for(int i=0;i<4;i++){if(i)rows<<',';vec(rows,e.basis[i]);}rows<<"],\"points\":[";bool sep=false;for(auto x:e.points){if(sep)rows<<',';sep=true;vec(rows,x);}rows<<"],\"solutions\":[";sep=false;for(auto x:sol){if(sep)rows<<',';sep=true;vec(rows,x);}rows<<"]}";cases++;}need(cases==5,"all five public planted charts");std::string text="{\"cases\":["+rows.str()+"],\"count\":5}";need(std::chrono::duration<double>(Clock::now()-start).count()<82,"native serialized deadline");std::cout<<text<<'\n';}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
